import random
import struct
from typing import List, Tuple

# Generator for Bayer raw pixel bytes suitable for LibRaw open_bayer fuzz stubs.
# The fuzzer stub will:
#  - choose width/height in [2..65]
#  - cap total need to <= 2048 bytes and treat pixels as up to 2 bytes each
#  - pass the returned buffer as FUZZ_PARAM_STR to provide raw data
# Our goal: produce buffers that are internally consistent and interesting
# patterns for demosaic/black subtraction/etc., while being valid byte content.

MAX_OUT = 4096

def _make_checkerboard(w: int, h: int, bitdepth: int) -> bytes:
    # Create a Bayer-friendly checkerboard gradient that varies per 2x2 tile.
    # bitdepth 8 or 16 -> produce bytes accordingly (little-endian for 16b).
    maxv = (1 << bitdepth) - 1
    lines: List[bytes] = []
    for y in range(h):
        row = bytearray()
        for x in range(w):
            # Basic gradients and per-channel emphasis:
            # Alternate per-pixel base to give demosaic something to do.
            base = ((x * 13 + y * 31) & maxv)
            # Modulate by 2x2 Bayer tile position to create distinct RG/GB stats
            if ((x ^ y) & 1) == 0:
                val = (base * 3) // 4  # slightly darker
            else:
                val = min(maxv, base + (maxv // 8))  # slightly brighter
            if bitdepth == 8:
                row.append(val & 0xFF)
            else:
                row += struct.pack('<H', val & 0xFFFF)
        lines.append(bytes(row))
    return b''.join(lines)

def _embed_margins(buf: bytes, w: int, h: int, bpp: int, lm: int, tm: int, rm: int, bm: int) -> bytes:
    # Darken margins to simulate optical black. The lib uses margins metadata, but
    # making edges darker increases realism and exercises black subtraction.
    ba = bytearray(buf)
    def set_px(x: int, y: int, v: int):
        idx = (y * w + x) * bpp
        if bpp == 1:
            ba[idx] = v & 0xFF
        else:
            # little-endian 16b
            ba[idx] = v & 0xFF
            ba[idx+1] = (v >> 8) & 0xFF
    maxv = 255 if bpp == 1 else 65535
    dark = maxv // 32
    # top margin rows
    for y in range(tm):
        for x in range(w):
            set_px(x, y, dark)
    # bottom margin rows
    for y in range(h - bm, h):
        for x in range(w):
            set_px(x, y, dark)
    # left/right columns for remaining rows
    for y in range(tm, h - bm):
        for x in range(lm):
            set_px(x, y, dark)
        for x in range(w - rm, w):
            set_px(x, y, dark)
    return bytes(ba)

def _choose_dims(rng: random.Random) -> Tuple[int,int,int,int,int,int]:
    # Mirror stub ranges: w,h in [2..65]; margins < w/2 or h/2
    w = rng.randint(2, 65)
    h = rng.randint(2, 65)
    lm = rng.randint(0, max(0, w//2 - 1)) if w >= 2 else 0
    rm = rng.randint(0, max(0, w//2 - 1)) if w >= 2 else 0
    tm = rng.randint(0, max(0, h//2 - 1)) if h >= 2 else 0
    bm = rng.randint(0, max(0, h//2 - 1)) if h >= 2 else 0
    return w, h, lm, tm, rm, bm

def _pick_bpp_and_depth(rng: random.Random, w: int, h: int) -> Tuple[int,int]:
    # The stub assumes up to 2 bytes per pixel and caps to 2048 bytes.
    # Choose 8bpp when 16bpp would exceed the cap to keep input fully used.
    if w * h * 2 <= 2048 and rng.random() < 0.7:
        return 2, 16
    return 1, 8

def _compose_pattern_set(rng: random.Random, w: int, h: int, bpp: int) -> bytes:
    # Build one of several interesting layouts within the size cap.
    # Alternate between: checkerboard, horizontal ramp, vertical ramp, stripes.
    choice = rng.randint(0, 3)
    if choice == 0:
        return _make_checkerboard(w, h, 8 if bpp == 1 else 16)
    maxv = 255 if bpp == 1 else 65535
    if choice == 1:
        # horizontal ramp
        ba = bytearray()
        for y in range(h):
            for x in range(w):
                v = (x * maxv) // max(1, (w - 1))
                if bpp == 1:
                    ba.append(v & 0xFF)
                else:
                    ba += struct.pack('<H', v)
        return bytes(ba)
    if choice == 2:
        # vertical ramp
        ba = bytearray()
        for y in range(h):
            vrow = (y * maxv) // max(1, (h - 1))
            for x in range(w):
                if bpp == 1:
                    ba.append(vrow & 0xFF)
                else:
                    ba += struct.pack('<H', vrow)
        return bytes(ba)
    # stripes per 2 rows/cols
    ba = bytearray()
    for y in range(h):
        for x in range(w):
            band = ((x // 2) + (y // 2)) & 1
            v = maxv // (4 if band == 0 else 1)
            if bpp == 1:
                ba.append(v & 0xFF)
            else:
                ba += struct.pack('<H', v)
    return bytes(ba)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose dimensions and pixel depth consistent with the stub caps
    w, h, lm, tm, rm, bm = _choose_dims(rng)
    bpp, bitdepth = _pick_bpp_and_depth(rng, w, h)

    # Ensure total size within the stub "need" cap (<= 2048)
    total = w * h * bpp
    if total > 2048:
        # shrink width/height proportionally to fit
        # prioritize reducing height (makes differing row behavior still visible)
        max_pixels = 2048 // bpp
        if max_pixels < 1:
            max_pixels = 1
        # keep width at least 2, compute height accordingly
        w = max(2, min(w, int(max_pixels ** 0.5)))
        h = max(2, min(h, max_pixels // w))
        total = w * h * bpp
        # adjust margins to fit new dims
        lm = min(lm, max(0, w//2 - 1))
        rm = min(rm, max(0, w//2 - 1))
        tm = min(tm, max(0, h//2 - 1))
        bm = min(bm, max(0, h//2 - 1))

    # Compose pixel data with structured patterns
    buf = _compose_pattern_set(rng, w, h, bpp)

    # Embed darker margins to simulate optical black areas (valid data still)
    buf = _embed_margins(buf, w, h, bpp, lm, tm, rm, bm)

    # Optionally append a small tail of zeros or repeated pattern to exactly
    # match the stub resizing behavior (it will resize up if our buffer is short).
    # We intentionally return exactly total bytes so the fuzzer won't need to pad.
    if len(buf) != total:
        buf = buf[:total].ljust(total, b"\x00")

    # As FUZZ_PARAM_STR is also used for filenames elsewhere, but in these
    # target stubs it is only used as the Bayer data buffer. Return raw bytes.
    return buf[: min(len(buf), MAX_OUT)]
